package com.sphere.core.clhep.geometry;

import com.sphere.core.clhep.vector.Hep3Vector;

/**
 * CLHEP's HepGeom::Vector3D&lt;double&gt; (Geometry/Vector3D.h, Vector3D.cc): a displacement, which a
 * transformation turns by its rotation only. Generated by gen_geometry.py.
 */
public class Vector3D extends BasicVector3D {

    public Vector3D() {
        super();
    }

    public Vector3D(double x1, double y1, double z1) {
        super(x1, y1, z1);
    }

    /** From the first three of an array. */
    public Vector3D(float[] a) {
        super(a[0], a[1], a[2]);
    }

    public Vector3D(double[] a) {
        super(a[0], a[1], a[2]);
    }

    public Vector3D(BasicVector3DF v) {
        super(v);
    }

    public Vector3D(Hep3Vector v) {
        super(v.x(), v.y(), v.z());
    }

    public Vector3D(BasicVector3D v) {
        super(v);
    }

    /** This vector turned by m's rotation. */
    public Vector3D transform(Transform3D m) {
        final double vx = x();
        final double vy = y();
        final double vz = z();
        set((m.xx() * vx + m.xy() * vy + m.xz() * vz),
            (m.yx() * vx + m.yy() * vy + m.yz() * vz),
            (m.zx() * vx + m.zy() * vy + m.zz() * vz));
        return this;
    }
}
